style.css:
@-moz-document domain("scratch.mit.edu") {
/* Background Gradient */
  body, .main-content, html {
    background: linear-gradient(135deg, #87CEFA, #1E90FF, #000080) !important;
    color: #ffffff !important;
  }

  /* Navbar Styling */
  .site-nav, .navigation {
    background: linear-gradient(90deg, #1E90FF, #000080) !important;
    color: white !important;
    border-bottom: 2px solid #87CEFA !important;
  }

  /* Buttons */
  button, .button, .button:hover, .button:focus {
    background: linear-gradient(to bottom right, #00BFFF, #0000CD) !important;
    color: white !important;
    border: none !important;
  }

  /* Links */
  a, a:visited {
    color: #add8e6 !important;
  }

  a:hover {
    color: #ffffff !important;
    text-decoration: underline !important;
  }

  /* Project Cards */
  .project-thumb, .thumbnail {
    border: 2px solid #1E90FF !important;
    background-color: rgba(0, 0, 128, 0.1) !important;
  }

  /* Footer */
  footer, .footer {
    background: linear-gradient(to top, #000080, #1E90FF) !important;
    color: white !important;
  }

  /* Text Inputs */
  input, textarea, select {
    background-color: #1e1e3f !important;
    color: #ffffff !important;
    border: 1px solid #87CEFA !important;
  }

  /* Scrollbar */
  ::-webkit-scrollbar {
    width: 10px;
  }
  ::-webkit-scrollbar-track {
    background: #000040;
  }
  ::-webkit-scrollbar-thumb {
    background: linear-gradient(#00BFFF, #000080);
    border-radius: 5px;
  }
}
